{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Pirprofen, the closest structural analogue (2-arylpropionic acid NSAID), showed a high and uniform degree of oral bioavailability in volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Naproxen, a related 2-arylpropionic acid NSAID, has an absolute oral bioavailability of 99% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Flurbiprofen, another close analogue, is almost completely available (~92%) after oral administration in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Ketoprofen, a structurally similar 2-arylpropionic acid, has an average absolute oral bioavailability of 92% versus intravenous administration in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ibuprofen, a direct analogue, is essentially 100% bioavailable compared with intravenous ibuprofen in a crossover human study.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carprofen, a 2-arylpropionic acid NSAID. All closely related propionic acid NSAIDs—pirprofen, naproxen, flurbiprofen, ketoprofen, and ibuprofen—show high oral bioavailability (70–100%) in humans, including multiple absolute bioavailability studies. The shared carboxylic acid and alpha-methyl propionate pharmacophore, along with the absence of known absorption-limiting features, strongly support oral bioavailability well above the 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for carprofen was retrieved; the prediction relies on close structural analogues.",
    "One outlier ibuprofen record (C24) reports 25% bioavailability, but it is inconsistent with multiple absolute bioavailability studies and was not used as material evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

